  async function hydrateSubscriptionState(id){if(!client||!user)return;const buttons=[...document.querySelectorAll(`button[data-action="subscription-toggle"][data-id="${CSS.escape(id)}"]`)];if(!buttons.length)return;const r=await client.from('whisper_subscriptions').select('whisper_id').eq('whisper_id',id).eq('user_id',user.id).maybeSingle();if(r.error)return;const active=!!r.data;buttons.forEach(b=>{b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));b.textContent=active?'✓ Following post':'＋ Follow post';b.title='Follow this post to receive notifications about new replies.'})}
