  async function my(){if(!user){app.innerHTML=shell('My reflections')+`<div class="auth-box"><h1>Your reflections</h1><p>Sign in to keep your reflections across devices and join conversations.</p><button class="btn" data-action="auth">Sign in / Create account</button></div>`;return}app.innerHTML=shell('My reflections','Your reflections, all in one place')+`<div id="feed" class="feed"><div class="empty">Loading…</div></div>`;try{const xs=await listMine();document.getElementById('feed').innerHTML=xs.length?loadCards(xs):`<div class="empty">You haven't shared a reflection yet.</div>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{} )}catch(e){document.getElementById('feed').innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry">Try again</button></div>`}}
  async function renderThoughtLineage(id){const slot=document.getElementById('thoughtLineage');if(!slot||!client)return;try{const [incoming,outgoing]=await Promise.all([client.from('whisper_links').select('source_whisper_id,link_type,created_at').eq('target_whisper_id',id).order('created_at',{ascending:false}).limit(6),client.from('whisper_links').select('target_whisper_id,link_type,created_at').eq('source_whisper_id',id).order('created_at',{ascending:false}).limit(6)]);if(incoming.error||outgoing.error)throw incoming.error||outgoing.error;const sourceIds=(incoming.data||[]).map(x=>x.source_whisper_id);const targetIds=(outgoing.data||[]).map(x=>x.target_whisper_id);const ids=[...new Set([...sourceIds,...targetIds])];if(!ids.length){slot.innerHTML='';return}const rows=await client.from('whispers').select('id,body,identity_mode,author_id,created_at').in('id',ids);if(rows.error)throw rows.error;const map=new Map((rows.data||[]).map(x=>[x.id,x]));const label=t=>t==='changed'?'Changed thinking':'Developed thought';const incomingHtml=(incoming.data||[]).map(l=>map.get(l.source_whisper_id)).filter(Boolean).map(w=>`<button class="lineage-item" data-action="open" data-id="${esc(w.id)}"><span class="lineage-label">${esc(label((incoming.data||[]).find(l=>l.source_whisper_id===w.id)?.link_type))}</span><span>${esc(w.body)}</span></button>`).join('');const outgoingHtml=(outgoing.data||[]).map(l=>map.get(l.target_whisper_id)).filter(Boolean).map(w=>`<button class="lineage-item" data-action="open" data-id="${esc(w.id)}"><span class="lineage-label">Continued from this reflection</span><span>${esc(w.body)}</span></button>`).join('');slot.innerHTML=`<section class="thought-lineage-card"><div class="eyebrow">Thought journey</div><h3>This reflection has a path</h3>${incomingHtml?`<div class="lineage-group"><strong>Developed from</strong>${incomingHtml}</div>`:''}${outgoingHtml?`<div class="lineage-group"><strong>Developed into</strong>${outgoingHtml}</div>`:''}</section>`}catch{slot.innerHTML=''}}
  async function openWhisper(id){const target=`#whisper/${encodeURIComponent(id)}`;app.innerHTML=`<div class="page-head"><a href="#home" class="back-btn">← Back</a></div><article class="thread"><div class="loading-bar"></div><p class="hint">Opening reflection…</p></article><section class="comments"><h3>Replies</h3><div class="empty">Loading discussion…</div></section>`;let w=null;try{w=await getWhisper(id);if(user&&!w){const mine=await listMine();w=mine.find(x=>x.id===id)}}catch(e){if((location.hash||'').split('?')[0]===target)app.innerHTML=`<div class="error">${esc(e?.message||'This reflection could not be opened.')}</div><button class="btn ghost" data-action="retry">Try again</button>`;return}if((location.hash||'').split('?')[0]!==target)return;if(!w){app.innerHTML='<div class="error">This reflection is unavailable or you no longer have permission to view it.</div><a class="btn ghost" href="#home">Back to Home</a>';return}currentWhisper=w;if(user)client.from('whisper_history').upsert({user_id:user.id,whisper_id:w.id,viewed_at:new Date().toISOString()},{onConflict:'user_id,whisper_id'}).then(()=>{}).catch(()=>{});app.innerHTML=`<div class="page-head"><a href="#${w.author_id===user?.id?'my':'home'}" class="back-btn">← Back</a></div><article class="thread"><div class="whisper-meta"><span class="name">${w.identity_mode==='real'?esc(w.author_id===user?.id?profileName():(w.author_profile?.display_name||w.author_profile?.username||'Someone')):'Anonymous'}</span><span class="time">· ${fmt(w.created_at)}${w.updated_at!==w.created_at?' · edited':''}</span></div><div class="thread-body">${esc(w.body)}</div><div id="threadTags"><div class="empty">Loading tags…</div></div><div id="threadMedia"><div class="empty">Loading media…</div></div><div class="thread-actions"><button class="action" data-action="like" data-id="${esc(w.id)}" aria-pressed="false">♡ Like</button><button class="action" data-action="save-toggle" data-id="${esc(w.id)}" data-save-button="1" aria-pressed="false">▢ Memory</button><button class="action" data-action="share" data-id="${esc(w.id)}">↗ Share</button>${user?`<button class="action" data-action="subscription-toggle" data-id="${esc(w.id)}" aria-pressed="false" title="Follow this post to receive notifications about new replies.">＋ Follow post</button>`:``}<button class="action develop-primary" data-action="develop-thought" data-id="${esc(w.id)}">Develop this reflection</button>${w.author_id===user?.id?`<button class="action" data-action="changed-thinking" data-id="${esc(w.id)}">Has your thinking changed?</button>`:''}${w.author_id===user?.id?`<button class="action" data-action="edit" data-id="${esc(w.id)}">Edit</button><button class="action danger-text" data-action="delete" data-id="${esc(w.id)}">Delete</button>`:`<button class="action" data-action="report" data-id="${esc(w.id)}" title="Report possible rule violations, not disagreement">Report</button>`}</div></article><section id="thoughtLineage" class="thought-lineage"></section><section id="relatedReflections" class="related-reflections"></section><section class="comments"><h3>Replies</h3><div id="commentArea"><div class="empty">Loading replies…</div></div></section>`;if(user){hydrateSaveStates([w]).catch(()=>{});hydrateSubscriptionState(id).catch(()=>{})}const mediaPromise=listMedia('whisper',id).catch(()=>[]);const commentsPromise=(client&&w.visibility!=='private')?renderComments(w.id):Promise.resolve();const media=await mediaPromise;if((location.hash||'').split('?')[0]!==target)return;const slot=document.getElementById('threadMedia');if(slot)slot.innerHTML=mediaPreview(media);const tg=await client.from('whisper_tags').select('*').eq('whisper_id',id);if((location.hash||'').split('?')[0]!==target)return;const tagSlot=document.getElementById('threadTags');if(tagSlot)tagSlot.innerHTML=tagHTML(tg.error?[]:(tg.data||[]));renderThoughtLineage(id).catch(()=>{});renderRelatedReflections(id).catch(()=>{});await commentsPromise;const match=(location.hash.split('?')[1]||'').match(/(?:^|&)comment=([^&]+)/);if(match){setTimeout(()=>document.getElementById('comment-'+decodeURIComponent(match[1]))?.scrollIntoView({behavior:'smooth',block:'center'}),60)}}

  function commentHTML(c,all,media=[],reactionMap=new Map()){const name=c.profiles?.display_name||c.profiles?.username||'Someone';const kids=all.filter(x=>x.parent_comment_id===c.id);const mine=c.author_id===user?.id;const r=reactionMap.get(c.id)||{like:0,dislike:0,mine:null};return `<div class="comment ${c.parent_comment_id?'reply':''}" id="comment-${esc(c.id)}"><div class="comment-meta"><span class="comment-author">${esc(name)}</span> · ${fmt(c.created_at)}${c.updated_at!==c.created_at?' · edited':''}</div><div class="comment-body">${esc(c.body)}</div>${mediaPreview(media.filter(m=>m.comment_id===c.id))}<div class="comment-actions">${user?`<button class="action ${r.mine==='like'?'active':''}" data-action="comment-reaction" data-reaction="like" data-comment="${esc(c.id)}">♥ <span class="comment-reaction-count" data-reaction="like">${r.like}</span></button><button class="action" data-action="reply-comment" data-comment="${esc(c.id)}">↩ Reply</button>`:''}<button class="action" data-action="share-comment" data-whisper="${esc(c.whisper_id)}" data-comment="${esc(c.id)}">↗ Share</button>${mine?`<button class="action" data-action="edit-comment" data-comment="${esc(c.id)}">Edit</button><button class="action danger-text" data-action="delete-comment" data-comment="${esc(c.id)}">Delete</button>`:user?`<button class="action" title="Report possible rule violations, not disagreement" data-action="report-comment" data-comment="${esc(c.id)}">Report</button>`:''}</div>${kids.map(x=>commentHTML(x,all,media,reactionMap)).join('')}</div>`}
  async function renderComments(id){const el=document.getElementById('commentArea');try{const cs=await listComments(id);let media=[];let reactions=[];if(client&&cs.length){const [mr,rr]=await Promise.all([client.from('comment_media').select('*').in('comment_id',cs.map(c=>c.id)),loadCommentReactions(cs.map(c=>c.id))]);if(!mr.error)media=await signMedia(mr.data||[]);reactions=rr}const reactionMap=new Map();reactions.forEach(x=>{const r=reactionMap.get(x.comment_id)||{like:0,dislike:0,mine:null};r[x.reaction]=(r[x.reaction]||0)+1;if(x.user_id===user?.id)r.mine=x.reaction;reactionMap.set(x.comment_id,r)});el.innerHTML=(user?`<form class="reply-form" id="replyForm"><input id="replyInput" maxlength="3000" placeholder="Reply to this Whisper…"><button class="btn">Reply</button></form>${attachmentPicker('reply')}`:'<div class="notice">Sign in to reply.</div>')+(cs.length?cs.map(c=>!c.parent_comment_id?commentHTML(c,cs,media,reactionMap):'').join(''):'<div class="empty">No replies yet. Be the first to add one.</div>');if(user)bindMediaPicker('reply');}catch(e){el.innerHTML=`<div class="error">${esc(e.message)}<br><button class="btn ghost" data-action="retry-comments">Try again</button></div>`}}
    function tagHTML(tags){if(!tags?.length)return'';return `<div class="tag-row">${tags.map(t=>`<span class="tag-pill">${esc(t.tag_type)}: ${esc(t.tag_value)}</span>`).join('')}</div>`}
  function collectTags(){const valueFor=(key)=>{const el=composerEl('#tag'+key);if(!el)return'';if(el.value==='__custom')return(composerEl('#tag'+key+'Custom')?.value||'').trim();return el.value.trim()};const base=[['location','Location'],['feeling','Feeling'],['idea','Idea'],['vibe','Vibe']].map(([type,key])=>({tag_type:type,tag_value:valueFor(key)})).filter(x=>x.tag_value);const body=composerEl('#whisperText')?.value||'';const mentions=[...body.matchAll(/@([a-zA-Z0-9_]{2,30})/g)].map(m=>m[1].toLowerCase());return base.concat([...new Set(mentions)].map(v=>({tag_type:'person',tag_value:v})).filter(x=>x.tag_value))}
