  async function groups(){if(!user){app.innerHTML=shell('Circles','Communities around reflections and shared interests')+`<div class="auth-box"><p>Sign in to discover Circles.</p><button class="btn" data-action="auth">Sign in / Create account</button></div>`;return}app.innerHTML=shell('Circles','Communities around reflections and shared interests')+`<section class="group-create"><button class="btn" data-action="create-group">＋ Create a Circle</button></section><section><h2>Popular Circles</h2><div id="popularCircles" class="group-list"><div class="empty">Finding popular Circles…</div></div></section><section><h2>All Circles</h2><div id="groupList" class="group-list"><div class="empty">Loading Circles…</div></div></section>`;try{const r=await client.from('groups').select('*').order('created_at',{ascending:false}).limit(80);if(r.error)throw r.error;const gs=r.data||[];const ids=gs.map(g=>g.id);const mr=ids.length?await client.from('group_members').select('group_id').in('group_id',ids):{data:[],error:null};const counts={};(mr.data||[]).forEach(x=>counts[x.group_id]=(counts[x.group_id]||0)+1);const sorted=[...gs].sort((a,b)=>(counts[b.id]||0)-(counts[a.id]||0));const mine=new Set((mr.data||[]).map(x=>x.group_id));const renderCircle=g=>`<article class="group-card"><div><h3><a href="#circle/${esc(g.id)}">${esc(g.name)}</a></h3><p>${esc(g.description||'')}</p><div class="hint">${counts[g.id]||0} member${counts[g.id]===1?'':'s'}${g.location_city?` · ${esc(g.location_city)}`:''}</div></div>${mine.has(g.id)?`<a class="btn ghost" href="#circle/${esc(g.id)}">Open Circle</a>`:`<button class="btn ghost" data-action="join-group" data-group-id="${esc(g.id)}">Join</button>`}</article>`;document.getElementById('popularCircles').innerHTML=sorted.slice(0,6).map(renderCircle).join('')||'<div class="empty">No Circles yet.</div>';document.getElementById('groupList').innerHTML=gs.map(renderCircle).join('')||'<div class="empty">No Circles yet.</div>'}catch(e){document.getElementById('groupList').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
  async function loadCircleMessages(id){const r=await client.from('circle_messages').select('id,sender_id,body,created_at').eq('circle_id',id).order('created_at',{ascending:false}).limit(60);if(r.error)throw r.error;const ids=[...new Set((r.data||[]).map(x=>x.sender_id))];const pr=ids.length?await client.from('profiles').select('id,username,display_name').in('id',ids):{data:[],error:null};if(pr.error)throw pr.error;const pm=new Map((pr.data||[]).map(x=>[x.id,x]));return (r.data||[]).reverse().map(m=>({...m,profile:pm.get(m.sender_id)||null}))}
