  async function circle(id){if(!user){openAuth('signin');return}app.innerHTML=shell('Circle','Loading Circle…')+`<div id="circlePage" class="circle-page"><div class="empty">Loading…</div></div>`;try{const g=await client.from('groups').select('*').eq('id',id).maybeSingle();if(g.error)throw g.error;if(!g.data)throw new Error('Circle not found.');const members=await client.from('group_members').select('user_id,role,created_at').eq('group_id',id);if(members.error)throw members.error;const ids=[...new Set((members.data||[]).map(x=>x.user_id))];const pr=ids.length?await client.from('profiles').select('id,username,display_name,avatar_path,location_city').in('id',ids):{data:[],error:null};if(pr.error)throw pr.error;const pm=new Map((pr.data||[]).map(p=>[p.id,p]));const wall=ids.length?await client.from('whispers').select('*').in('author_id',ids).eq('visibility','public').order('created_at',{ascending:false}).limit(30):{data:[],error:null};if(wall.error)throw wall.error;const xs=await decorateAuthors(wall.data||[]);const me=members.data?.some(x=>x.user_id===user.id);const memberHtml=(members.data||[]).map(m=>{const p=pm.get(m.user_id)||{};return `<div class="circle-member"><div class="avatar small">${avatarMarkup(p,p.display_name||p.username)}</div><div><strong>${esc(p.display_name||p.username||'Unknown')}</strong><div class="hint">@${esc(p.username||'')}${m.role==='owner'?' · owner':''}</div></div></div>`}).join('');document.getElementById('circlePage').innerHTML=`<section class="circle-hero"><h2>${esc(g.data.name)}</h2><p>${esc(g.data.description||'')}</p><div class="hint">${members.data?.length||0} members${g.data.location_city?` · ${esc(g.data.location_city)}`:''}</div><div class="profile-actions">${me?'<span class="tag-pill">You are a member now</span>':`<button class="btn" data-action="join-group" data-group-id="${esc(id)}">Join Circle</button>`}<a class="btn ghost" href="#messages">Circle messaging</a><a class="btn ghost" href="#live?circle=${encodeURIComponent(id)}">Live adda</a></div></section><section><div class="section-head"><h3>Circle members</h3>${g.data.owner_id===user.id?`<button class="btn ghost" data-action="circle-add-member" data-group-id="${esc(id)}">＋ Add members</button>`:''}</div><div class="circle-members">${memberHtml||'<div class="empty">No members yet.</div>'}</div></section><section class="circle-activity"><h3>Circle adda</h3><div id="circleMessages" class="circle-messages"></div><form id="circleMessageForm" class="message-form"><input id="circleMessageInput" maxlength="5000" placeholder="Write to the Circle…"><button class="btn">Send</button></form></section><section><h3>Circle wall — members’ reflections</h3><div class="feed" id="circleFeed">${xs.length?loadCards(xs):'<div class="empty">No public Whispers from Circle members yet.</div>'}</div></section>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{});await renderCircleMessages(id);if(window._circleRealtime)client.removeChannel(window._circleRealtime);window._circleRealtime=client.channel('mindrid-circle-'+id).on('postgres_changes',{event:'INSERT',schema:'public',table:'circle_messages',filter:'circle_id=eq.'+id},()=>renderCircleMessages(id)).subscribe()}catch(e){document.getElementById('circlePage').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
