  function profileSettings(){if(!user){openAuth('signin');return}const p=currentProfile||{};modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');modal.innerHTML=`<div class="modal-card"><div class="modal-title"><h2>Edit profile</h2><button class="btn ghost" data-action="close">Close</button></div><form id="profileForm"><div class="field"><label>Profile picture</label><input id="avatarFile" type="file" accept="image/*"><div class="hint">JPG, PNG or WebP · up to 5 MB.</div></div><div class="field"><label>Background photo</label><input id="backgroundFile" type="file" accept="image/*"><label class="check"><input id="clearBackground" type="checkbox"> Remove current background</label><div class="hint">This appears behind your profile header · up to 8 MB.</div></div><div class="field"><label>Display name</label><input id="displayName" maxlength="80" value="${esc(p.display_name||'')}"></div><div class="field"><label>Bio</label><textarea id="bio" maxlength="500">${esc(p.bio||'')}</textarea></div><div class="field"><label>Country</label><input id="profileCountry" value="${esc(p.location_country||'')}"></div><div class="field"><label>City / area</label><input id="profileCity" value="${esc(p.location_city||'')}"></div><div class="field"><label>Profile vibe</label><select id="themeKey" class="select"><option value="auto" ${(p.theme_key||'auto')==='auto'?'selected':''}>Auto — follow the vibe of my latest reflection</option><option value="sky" ${p.theme_key==='sky'?'selected':''}>Sky</option><option value="lavender" ${p.theme_key==='lavender'?'selected':''}>Lavender</option><option value="mint" ${p.theme_key==='mint'?'selected':''}>Mint</option><option value="sunset" ${p.theme_key==='sunset'?'selected':''}>Sunset</option><option value="mono" ${p.theme_key==='mono'?'selected':''}>Monochrome</option></select></div><div class="field"><label>Interests (comma separated)</label><input id="interests" value="${esc((p.interests||[]).join(', '))}"></div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close">Cancel</button><button class="btn">Save profile</button></div></form></div>`}
  async function saveProfile(e){e.preventDefault();const btn=e.target.querySelector('.btn:not(.ghost)');await runAction(btn,'Saving…','Profile updated.',async()=>{const oldAvatar=currentProfile?.avatar_path||null,oldBackground=currentProfile?.background_path||null;let avatar_path=oldAvatar,background_path=oldBackground,uploaded=[];const f=document.getElementById('avatarFile')?.files?.[0],bf=document.getElementById('backgroundFile')?.files?.[0],clearBackground=!!document.getElementById('clearBackground')?.checked;if(f){if(f.size>5*1024*1024)throw new Error('Profile photo must be 5 MB or smaller.');const u=await uploadMedia(f,'avatar');uploaded.push(u);avatar_path=u.storage_path}if(bf){if(bf.size>8*1024*1024)throw new Error('Background photo must be 8 MB or smaller.');const u=await uploadMedia(bf,'background');uploaded.push(u);background_path=u.storage_path}else if(clearBackground){background_path=null}const interests=document.getElementById('interests').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,30);let lastWhisper='',lastVibe=currentProfile?.last_whisper_vibe||'';if(!lastWhisper){const lw=await client.from('whispers').select('body,id').eq('author_id',user.id).order('created_at',{ascending:false}).limit(1).maybeSingle();lastWhisper=lw.data?.body||'';if(lastWhisper){const tv=await client.from('whisper_tags').select('tag_value').eq('whisper_id',lw.data.id).eq('tag_type','vibe').limit(1).maybeSingle();lastVibe=tv.data?.tag_value||''}}const r=await client.from('profiles').update({display_name:document.getElementById('displayName').value.trim(),bio:document.getElementById('bio').value.trim(),location_country:document.getElementById('profileCountry').value.trim(),location_city:document.getElementById('profileCity').value.trim(),interests,avatar_path,background_path,theme_key:document.getElementById('themeKey').value,last_whisper_vibe:lastVibe}).eq('id',user.id);if(r.error){await removeUploadedMedia(uploaded);throw r.error}if(f&&oldAvatar&&oldAvatar!==avatar_path)await removeUploadedMedia([{storage_path:oldAvatar}]);if((bf||clearBackground)&&oldBackground&&oldBackground!==background_path)await removeUploadedMedia([{storage_path:oldBackground}]);await ensureProfile(true);closeModal();account()})}

  async function accountActionsDialog(){if(!user)return;modal.classList.remove('hidden');modal.innerHTML=`<div class="modal-card"><div class="modal-title"><h2>Account</h2><button class="btn ghost" data-action="close">Close</button></div><p>Deactivate hides your profile and stops normal discovery. Deletion permanently removes your account data and cannot be undone.</p><div class="modal-actions"><button class="btn ghost" data-action="deactivate">Deactivate account</button><button class="btn danger" data-action="delete-account">Delete account</button></div></div>`}
  async function ensureAAL2(){const f=await client.auth.mfa.listFactors();if(f.error)throw f.error;const factor=(f.data?.totp||[]).find(x=>x.status==='verified');if(!factor)return;const aal=await client.auth.mfa.getAuthenticatorAssuranceLevel();if(aal.error)throw aal.error;if(aal.data?.currentLevel==='aal2')return;const ch=await client.auth.mfa.challenge({factorId:factor.id});if(ch.error)throw ch.error;const code=prompt('Enter your six-digit authenticator code to continue:');if(!code)throw new Error('Two-factor authentication is required for this action.');const v=await client.auth.mfa.verify({factorId:factor.id,challengeId:ch.data.id,code:code.trim()});if(v.error)throw v.error}
  async function doDeactivate(){if(!confirm('Deactivate your account? You can reactivate later by signing in and choosing Reactivate.'))return;await ensureAAL2();const r=await client.rpc('mindrid_deactivate_account');if(r.error)throw r.error;await client.auth.signOut();toast('Account deactivated.')}
  async function doDeleteAccount(){if(!confirm('Permanently delete your mindRID account and its data? This cannot be undone.'))return;await ensureAAL2();const r=await client.rpc('mindrid_delete_account');if(r.error)throw r.error;user=null;currentProfile=null;closeModal();location.hash='#home';toast('Account deleted.')}
  async function person(id){if(!client||!id)return;app.innerHTML=shell('Profile','A person on mindRID')+`<div id="personPage"><div class="empty">Loading…</div></div>`;try{const r=await client.from('profiles').select('id,username,display_name,bio,location_city,location_country,background,background_path,interests,avatar_path,theme_key,is_deactivated').eq('id',id).eq('is_deactivated',false).maybeSingle();if(r.error)throw r.error;if(!r.data)throw new Error('Profile not found.');let p=r.data;if(p.avatar_path){const ar=await client.storage.from(MEDIA_BUCKET).createSignedUrl(p.avatar_path,3600);if(!ar.error)p={...p,avatar_url:ar.data.signedUrl}}if(p.background_path){const br=await client.storage.from(MEDIA_BUCKET).createSignedUrl(p.background_path,3600);if(!br.error)p={...p,background_url:br.data.signedUrl}}const w=await client.from('whispers').select('*').eq('author_id',id).eq('visibility','public').order('created_at',{ascending:false}).limit(30);if(w.error)throw w.error;const xs=await decorateAuthors(w.data||[]);const [followed,counts]=user&&id!==user.id?await Promise.all([getFollowState(id),followCounts(id)]):[false,await followCounts(id)];const theme=p.theme_key&&p.theme_key!=='auto'?p.theme_key:deriveAutoThemeFor(p,xs[0]);const cover=p.background_url?`style="background-image:url('${esc(p.background_url)}')"`:'';document.getElementById('personPage').innerHTML=`<section class="profile-header public-profile profile-theme-${esc(theme)}"><div class="profile-cover" ${cover}></div><div class="profile-avatar-wrap"><div class="avatar profile-avatar">${avatarMarkup(p,p.display_name||p.username)}</div></div><div class="profile-name">${esc(p.display_name||p.username||'Member')}</div><div class="profile-handle">@${esc(p.username||'')}</div>${p.bio?`<p>${esc(p.bio)}</p>`:''}<div class="profile-stats"><span><strong>${counts.followers}</strong> followers</span><span><strong>${counts.following}</strong> following</span></div><div class="common-row">${p.location_city?`<span class="tag-pill">📍 ${esc(p.location_city)}${p.location_country?', '+esc(p.location_country):''}</span>`:''}${(p.interests||[]).slice(0,6).map(x=>`<span class="tag-pill">${esc(x)}</span>`).join('')}</div>${user&&id!==user.id?`<div class="profile-actions"><button class="btn" data-action="${followed?'unfollow':'follow'}" data-user-id="${esc(id)}">${followed?'Following':'Follow'}</button><button class="btn ghost" data-action="connect" data-user-id="${esc(id)}">Connect</button><button class="btn ghost" data-action="message-user" data-user-id="${esc(id)}">Message</button></div>`:''}</section><section><div class="section-head"><h2>Wall</h2><span class="hint">Public reflections and conversation starters</span></div><div class="feed">${xs.length?loadCards(xs):'<div class="empty">No public Whispers yet.</div>'}</div></section>`;if(xs.length)hydrateFeedMedia(xs).catch(()=>{})}catch(e){document.getElementById('personPage').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
function deriveAutoThemeFor(p,last){const s=String(p?.last_whisper_vibe||'')+' '+String(last?.body||'');if(/sun|joy|hope|happy|bright|love/i.test(s))return'sunset';if(/rain|sad|quiet|blue|heavy|loss/i.test(s))return'sky';if(/nature|calm|peace|grow|green/i.test(s))return'mint';if(/dream|wonder|maybe|idea|creative/i.test(s))return'lavender';return'sky'}

  async function account(){if(!user){openAuth('signin');return}const p=currentProfile||{};const counts=await followCounts(user.id).catch(()=>({followers:0,following:0}));const theme=p.theme_key&&p.theme_key!=='auto'?p.theme_key:deriveAutoTheme();const cover=p.background_url?`style="background-image:url('${esc(p.background_url)}')"`:'';app.innerHTML=shell('Profile')+`<section class="profile-header profile-theme-${esc(theme)}"><div class="profile-cover" ${cover}></div><div class="profile-avatar-wrap"><div class="avatar profile-avatar">${avatarMarkup(p,profileName())}</div></div><div class="profile-name">${esc(profileName())}</div><div class="profile-handle">@${esc(p.username||'')}</div>${p.bio?`<p>${esc(p.bio)}</p>`:''}<div class="profile-stats"><span><strong>${counts.followers}</strong> followers</span><span><strong>${counts.following}</strong> following</span></div><div class="common-row">${p.location_city?`<span class="tag-pill">📍 ${esc(p.location_city)}${p.location_country?', '+esc(p.location_country):''}</span>`:''}${(p.interests||[]).slice(0,6).map(x=>`<span class="tag-pill">${esc(x)}</span>`).join('')}</div><div class="profile-actions"><button class="btn" data-action="edit-profile">Edit profile</button><a class="btn ghost" href="#followers">Followers</a><a class="btn ghost" href="#following">Following</a><button class="btn ghost" data-action="account-controls">Account controls</button><button class="btn ghost" data-action="signout">Sign out</button></div></section><div class="tabs"><a class="active" href="#account">Profile</a><a href="#my">My reflections</a><a href="#memory">Memory</a></div>`}
  let livePeer=null,liveChannel=null,liveRole=null;
  async function live(){if(!user){app.innerHTML=shell('Live','Audio and video conversations')+`<div class="auth-box"><p>Sign in to start or join a live conversation.</p><button class="btn" data-action="auth">Sign in</button></div>`;return}const q=new URLSearchParams(location.hash.split('?')[1]||'');const circleId=q.get('circle');app.innerHTML=shell('Live',circleId?'Live adda for this Circle.':'Audio/video conversations and live Circle adda.')+`<section class="live-card"><div class="live-actions"><button class="btn" data-action="live-start" data-mode="video">Start video</button><button class="btn ghost" data-action="live-start" data-mode="audio">Start audio</button><button class="btn danger" data-action="live-stop">End live</button></div><div class="field"><label>Join a room</label><div class="live-join"><input id="liveRoomId" placeholder="Room ID"><button class="btn ghost" data-action="live-join">Join</button></div></div><div id="liveStatus" class="status-line"></div><div class="live-stage"><video id="localVideo" autoplay muted playsinline></video><video id="remoteVideo" autoplay playsinline></video><audio id="remoteAudio" autoplay></audio></div></section>`}
  async function liveStart(mode){if(!client||!user)throw new Error('Sign in first.');const room=crypto.randomUUID();const q=new URLSearchParams(location.hash.split('?')[1]||'');const circleId=q.get('circle');location.hash='#live/'+room+'?host=1&mode='+mode+(circleId?'&circle='+encodeURIComponent(circleId):'')}
  async function liveJoin(room){if(!room)throw new Error('Enter a room ID.');location.hash='#live/'+encodeURIComponent(room)}
  async function initLive(room,host=false,mode='video'){if(!client||!user)return;const status=document.getElementById('liveStatus');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:mode==='video'});const local=document.getElementById('localVideo');if(local){local.srcObject=stream;local.style.display=mode==='video'?'block':'none'}liveRole=host?'host':'guest';livePeer=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});stream.getTracks().forEach(t=>livePeer.addTrack(t,stream));livePeer.ontrack=e=>{const v=document.getElementById('remoteVideo');const a=document.getElementById('remoteAudio');if(e.streams[0]){if(v){v.srcObject=e.streams[0];v.style.display=e.track.kind==='video'?'block':'none'}if(a)a.srcObject=e.streams[0]}};livePeer.onicecandidate=e=>{if(e.candidate)liveChannel?.send({type:'broadcast',event:'ice',payload:e.candidate})};liveChannel=client.channel('mindrid-live-'+room,{config:{broadcast:{self:false}}});liveChannel.on('broadcast',{event:'offer'},async({payload})=>{if(liveRole!=='guest')return;await livePeer.setRemoteDescription(payload);const answer=await livePeer.createAnswer();await livePeer.setLocalDescription(answer);liveChannel.send({type:'broadcast',event:'answer',payload:answer})}).on('broadcast',{event:'answer'},async({payload})=>{if(liveRole==='host')await livePeer.setRemoteDescription(payload)}).on('broadcast',{event:'ice'},async({payload})=>{try{await livePeer.addIceCandidate(payload)}catch{}});await liveChannel.subscribe();if(host){const offer=await livePeer.createOffer();await livePeer.setLocalDescription(offer);await liveChannel.send({type:'broadcast',event:'offer',payload:offer})}status.textContent=host?'Room ready. Share this room ID: '+room:'Connected to room. Waiting for the other side if needed.'}catch(e){if(status)status.textContent=e.message||'Camera/microphone access was not available.';toast(e.message||'Live setup failed.','error')}}
  function stopLive(){try{livePeer?.getSenders()?.forEach(s=>s.track?.stop());livePeer?.close();liveChannel?.unsubscribe()}catch{}livePeer=null;liveChannel=null;location.hash='#live'}
  function staticPage(title,body){app.innerHTML=`<section class="prose"><div class="info-nav"><a href="#home">← Home</a><span class="info-brand">mindRID</span><div class="info-links"><a href="#about">About</a><a href="#privacy">Privacy</a><a href="#terms">Terms</a><a href="#faq">FAQ</a><a href="#contact">Contact</a></div></div><h1>${esc(title)}</h1>${body}</section>`}
  async function listConversations(){if(!client||!user)throw new Error('Sign in to use private messages.');const r=await client.from('conversation_members').select('conversation_id').eq('user_id',user.id);if(r.error)throw r.error;const ids=[...new Set((r.data||[]).map(x=>x.conversation_id))];if(!ids.length)return[];const c=await client.from('conversations').select('id,created_at,updated_at,last_message_at').in('id',ids).order('last_message_at',{ascending:false});if(c.error)throw c.error;const rows=c.data||[];const members=await client.from('conversation_members').select('conversation_id,user_id').in('conversation_id',ids);if(members.error)throw members.error;const otherIds=[...new Set((members.data||[]).filter(x=>x.user_id!==user.id).map(x=>x.user_id))];const profiles=otherIds.length?await client.from('profiles').select('id,username,display_name,avatar_path').in('id',otherIds):{data:[],error:null};if(profiles.error)throw profiles.error;const pm=new Map((profiles.data||[]).map(x=>[x.id,x]));return rows.map(c=>{const m=(members.data||[]).find(x=>x.conversation_id===c.id&&x.user_id!==user.id);return {...c,other:m?pm.get(m.user_id)||{username:'Unknown'}:{username:'Unknown'}}})}
  async function findProfileByUsername(username){const r=await client.from('profiles').select('id,username,display_name,avatar_path').eq('username',username.toLowerCase()).eq('is_deactivated',false).maybeSingle();if(r.error)throw r.error;return r.data||null}
  async function startConversation(recipientId){if(!client||!user)throw new Error('Sign in to use private messages.');if(recipientId===user.id)throw new Error('You cannot message yourself.');const r=await client.rpc('mindrid_start_conversation',{recipient:recipientId});if(r.error)throw r.error;return r.data}
  async function sendMessage(conversationId,body){if(!client||!user)throw new Error('Sign in to send a message.');const r=await client.from('messages').insert({conversation_id:conversationId,sender_id:user.id,body:body.trim()}).select().single();if(r.error)throw r.error;return r.data}
  async function loadMessages(conversationId){const r=await client.from('messages').select('id,conversation_id,sender_id,body,created_at,updated_at').eq('conversation_id',conversationId).order('created_at',{ascending:true});if(r.error)throw r.error;return r.data||[]}
  async function openConversation(id){if(!user){openAuth('signin');return}app.innerHTML=shell('Messages','Private, one-to-one conversations')+`<div id="messageThread" class="message-thread"><div class="empty">Loading…</div></div>`;try{const cs=await listConversations(),c=cs.find(x=>x.id===id);if(!c)throw new Error('Conversation not found or unavailable.');const msgs=await loadMessages(id);app.innerHTML=shell('Messages',`Conversation with ${c.other.display_name||c.other.username||'Unknown'}`)+`<div class="message-toolbar"><button class="btn ghost" data-action="messages-home">← All messages</button></div><div class="message-thread" id="messageThread">${msgs.length?msgs.map(m=>`<div class="message ${m.sender_id===user.id?'mine':''}"><div class="message-bubble">${esc(m.body)}</div><div class="message-time">${fmt(m.created_at)}</div></div>`).join(''):`<div class="empty">No messages yet. Start the conversation.</div>`}</div><form id="messageForm" class="message-form"><input id="messageInput" maxlength=5000 placeholder="Write a private message…" autocomplete="off"><button class="btn">Send</button></form>`;const t=document.getElementById('messageThread');t.scrollTop=t.scrollHeight}catch(e){app.innerHTML=`${shell('Messages')}<div class="error">${esc(e.message)}</div>`}}
  async function messages(){if(!user){app.innerHTML=shell('Messages')+`<div class="auth-box"><h1>Private messages</h1><p>Sign in to send and receive private one-to-one messages.</p><button class="btn" data-action="auth">Sign in / Create account</button></div>`;return}app.innerHTML=shell('Messages','Search people and start a private conversation')+`<section class="message-start"><h2>New conversation</h2><div class="typeahead"><input id="messageSearch" placeholder="Search by name or username…" autocomplete="off"><div id="messageSuggestions" class="suggestions"></div></div><form id="newMessageForm" class="new-message-form"><input id="messageUsername" placeholder="Selected username" autocomplete="off" required><input id="firstMessage" maxlength=5000 placeholder="Write your first message…" required><button class="btn">Message</button></form><div id="messageStartStatus" class="status-line" aria-live="polite"></div></section><section id="conversationList" class="conversation-list"><div class="empty">Loading…</div></section>`;bindProfileSuggestions('messageSearch','messageSuggestions');try{const cs=await listConversations();const el=document.getElementById('conversationList');el.innerHTML=cs.length?cs.map(c=>`<a class="conversation" href="#messages/${encodeURIComponent(c.id)}"><div class="avatar">${avatarMarkup(c.other,c.other.display_name||c.other.username)}</div><div><strong>${esc(c.other.display_name||c.other.username||'Unknown')}</strong><div class="hint">@${esc(c.other.username||'')} · ${fmt(c.last_message_at||c.updated_at||c.created_at)}</div></div></a>`).join(''):`<div class="empty">No private conversations yet.</div>`}catch(e){document.getElementById('conversationList').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
  async function mfaDialog(){if(!user){openAuth('signin');return}const f=await client.auth.mfa.listFactors();const verified=(f.data?.totp||[]).filter(x=>x.status==='verified');modal.classList.remove('hidden');modal.innerHTML=`<div class="modal-card"><div class="modal-title"><h2>Two-factor authentication</h2><button class="btn ghost" data-action="close">Close</button></div><p>${verified.length?'2FA is enabled on this account. Keep a backup authenticator factor on another device because Supabase does not provide recovery codes.':'Add an authenticator app as a second factor. After enabling it, keep a backup authenticator factor on another device.'}</p>${verified.length?`<button class="btn ghost" data-action="mfa-disable">Disable 2FA</button>`:`<button class="btn" data-action="mfa-enroll">Enable 2FA</button>`}<div id="mfaArea"></div></div>`}
  async function mfaEnroll(){const r=await client.auth.mfa.enroll({factorType:'totp',friendlyName:'mindRID Authenticator'});if(r.error)throw r.error;modal.querySelector('#mfaArea').innerHTML=`<p>Scan this QR code with an authenticator app, then enter the six-digit code.</p><img class="mfa-qr" src="${esc(r.data.totp.qr_code)}" alt="2FA QR code"><div class="field"><input id="mfaCode" inputmode="numeric" maxlength="6" placeholder="6-digit code"></div><button class="btn" data-action="mfa-verify" data-factor-id="${esc(r.data.id)}">Verify and enable</button>`}
  async function mfaVerify(id){const ch=await client.auth.mfa.challenge({factorId:id});if(ch.error)throw ch.error;const code=document.getElementById('mfaCode')?.value.trim();if(!/^\d{6}$/.test(code))throw new Error('Enter the six-digit authenticator code.');const v=await client.auth.mfa.verify({factorId:id,challengeId:ch.data.id,code});if(v.error)throw v.error;closeModal();toast('Two-factor authentication enabled.')}
  async function mfaDisable(){const f=await client.auth.mfa.listFactors();const factor=(f.data?.totp||[]).find(x=>x.status==='verified');if(!factor)throw new Error('No active 2FA factor found.');const ch=await client.auth.mfa.challenge({factorId:factor.id});if(ch.error)throw ch.error;const code=prompt('Enter your current six-digit authenticator code to disable 2FA:');if(!code) return;const v=await client.auth.mfa.verify({factorId:factor.id,challengeId:ch.data.id,code:code.trim()});if(v.error)throw v.error;const d=await client.auth.mfa.unenroll({factorId:factor.id});if(d.error)throw d.error;closeModal();toast('Two-factor authentication disabled.')}
  function settings(){if(!user){openAuth('signin');return}app.innerHTML=shell('Settings')+`<section class="prose"><h2>Account & privacy</h2><p>Manage your profile, account state, discovery information and sign-in security.</p><button class="btn" data-action="edit-profile">Edit profile</button> <button class="btn ghost" data-action="account-controls">Account controls</button> <button class="btn ghost" data-action="mfa">Two-factor authentication</button><h2>Discovery</h2><p>For You uses the signals you choose to create — follows, Connections, interests and public Whisper context — to shape a personal stream. You can always switch to Following or Timeline.</p><h2>Profile appearance</h2><p>Your profile can use a background photo and a selected visual theme, or automatically follow the tone of your latest Whisper.</p><h2>Session</h2><p>You are automatically signed out after 40 minutes without activity on this device.</p></section>`}
  function about(){staticPage('About',`<div class="prose-hero"><span class="eyebrow">The idea</span><h2>Get rid of what you cannot safely carry alone.</h2><p>mindRID is a Social place where we lay What’s far too heavy for the heart, Yet far too deep to hide away.</p></div><h2>What mindRID is for</h2><p>mindRID is built around reflections rather than follower counts. You can write a reflection, choose how you are identified, decide who can see it, and enter conversations around it.</p><h2>Reflection-first, people-supported</h2><p>People, Connections, Circles, messaging, discovery and media exist to help reflections meet other reflections and develop through dialogue.</p><h2>Our privacy promise</h2><p class="privacy-promise">mindRID doesn't sell your emotion or data.</p><p>That promise is intended as a product policy: mindRID does not sell user emotion, thoughts or personal data. The Privacy page explains what information the service processes and why.</p><h2>Limits</h2><p>mindRID is a social platform, not therapy, emergency care, legal advice or a guarantee of absolute confidentiality.</p>`)}
  function privacy(){staticPage('Privacy',`<div class="prose-hero"><span class="eyebrow">Privacy</span><h2>Your reflections should remain yours.</h2><p class="privacy-promise">mindRID doesn't sell your emotion or data.</p></div><h2>Information we process</h2><p>Depending on the features you use, mindRID may process account credentials, profile information, reflections and replies, media attachments, connections, Circle membership, messages, notifications, location or interests that you choose to provide, and technical information required to operate the service.</p><h2>How we use information</h2><p>We use information to authenticate accounts, store and display content according to your visibility choices, provide search and discovery, deliver messages and notifications, maintain security, prevent abuse, and operate and improve the service.</p><h2>Anonymous reflections</h2><p>When you choose Anonymous, your public display identity is not shown to other users with that Whisper. Anonymous posting should not be understood as a promise that the service has no account-level record of authorship.</p><h2>Media</h2><p>Images, video and audio are stored separately from Whisper text and are subject to the same ownership and visibility controls.</p><h2>Sharing and providers</h2><p>mindRID uses infrastructure providers such as Supabase for authentication, database and media storage. Where third parties process information on behalf of mindRID, their access should be limited to the service functions they provide.</p><h2>Retention and deletion</h2><p>We retain information for as long as reasonably necessary to provide the service, meet security and legal obligations, and resolve disputes. Account deletion tools are provided in Settings; deletion may be subject to backups or legally required retention.</p><h2>Your choices</h2><p>You can control identity mode, visibility, profile information, connections and account status through the available controls. You may contact mindRID about privacy questions or deletion requests.</p><h2>Contact</h2><p>Privacy enquiries: <a href="mailto:tyeaawill@gmail.com">tyeaawill@gmail.com</a></p>`)}
  function terms(){staticPage('Terms',`<div class="prose-hero"><span class="eyebrow">Terms</span><h2>Use mindRID thoughtfully.</h2><p>These terms describe the basic rules for using the service.</p></div><h2>Eligibility and account</h2><p>You are responsible for the information you provide, keeping credentials secure, and activity performed through your account.</p><h2>User content</h2><p>You retain your rights in content you create. You grant mindRID the limited permission needed to host, reproduce, transmit, display and moderate that content so the service can function.</p><h2>Respect and safety</h2><p>Do not use mindRID for threats, harassment, hate, exploitation, unlawful targeting, impersonation, scams, privacy violations, malicious files or other prohibited conduct.</p><h2>Anonymous posting</h2><p>Anonymous is a display mode, not a licence to violate these terms or a guarantee of legal anonymity.</p><h2>Moderation</h2><p>Users can report content. mindRID may restrict, remove or suspend content or accounts where necessary to protect the service and its users.</p><h2>Availability</h2><p>mindRID may change, suspend or discontinue features. We aim for reliability but do not promise uninterrupted availability.</p><h2>Contact</h2><p>Questions about these terms: <a href="mailto:tyeaawill@gmail.com">tyeaawill@gmail.com</a></p>`)}
  function contact(){staticPage('Contact',`<div class="prose-hero"><span class="eyebrow">Contact</span><h2>Talk to mindRID.</h2><p>For product, privacy, safety, abuse or account matters, contact the service team.</p></div><div class="contact-grid"><div class="side-card"><h3>General</h3><p><a href="mailto:tyeaawill@gmail.com">tyeaawill@gmail.com</a></p></div><div class="side-card"><h3>Privacy & data</h3><p>Use the same address and put “Privacy” in the subject.</p></div><div class="side-card"><h3>Safety & abuse</h3><p>Include the relevant Whisper or profile link and a concise explanation.</p></div></div><p class="hint">Do not email passwords, authentication codes or unnecessary sensitive identification.</p>`)}
  function faq(){staticPage('FAQ',`<div class="prose-hero"><span class="eyebrow">FAQ</span><h2>How mindRID works.</h2></div><h2>Can I post anonymously?</h2><p>Yes. Anonymous changes what other users see as the public identity of the Whisper.</p><h2>Can I control who sees a Whisper?</h2><p>Yes. Public, private and selected-people visibility modes are available.</p><h2>Can I attach media?</h2><p>Yes. Whispers and replies support images, video and audio within the current size limits.</p><h2>Can I remove a media item?</h2><p>Yes. Media can be removed from your Whisper during editing, and selected media can be removed before posting.</p><h2>What are Circles?</h2><p>Circles are communities around shared interests or themes. Members can see the Circle wall and use Circle activities such as messaging and live adda.</p><h2>Can I add people to a Circle?</h2><p>Circle owners can add people from their network.</p><h2>Does mindRID sell my data?</h2><p>mindRID's product policy is that it does not sell your emotion or data. See Privacy for the information-processing details.</p><h2>Can I delete my account?</h2><p>Yes. Account controls are available in Settings, subject to the service's deletion and retention rules.</p>`)}
  function guidelines(){staticPage('Community Guidelines',`<div class="prose-hero"><span class="eyebrow">Community</span><h2>Make room for thoughts without making the space unsafe.</h2><p>mindRID welcomes disagreement, uncertainty, difficult questions and different perspectives.</p></div><h2>Not allowed</h2><p>Threats, targeted harassment, hate, sexual exploitation, scams, malicious activity, privacy violations, impersonation and unlawful abuse are not allowed.</p><h2>Disagreement is not a report reason by itself</h2><p>Report content when it may violate a rule. A different opinion is not automatically a violation.</p><h2>Anonymous posting</h2><p>Anonymous mode protects the public display identity, but the same community rules apply.</p>`)}
  function safety(){staticPage('Safety',`<div class="prose-hero"><span class="eyebrow">Safety</span><h2>Tools for control, reporting and boundaries.</h2><p>Use visibility controls, Connections, Block and Report to manage interactions.</p></div><h2>If something feels unsafe</h2><p>Leave the conversation, use Block or Report where appropriate, and preserve the relevant link if you need to contact the service team.</p><h2>Urgent danger</h2><p>mindRID is not an emergency service. For immediate danger, contact the appropriate local emergency service.</p>`)}
  function accessibility(){staticPage('Accessibility',`<div class="prose-hero"><span class="eyebrow">Accessibility</span><h2>mindRID should be usable by more people.</h2><p>We aim to provide readable contrast, keyboard-accessible controls, clear labels, responsive layouts and meaningful status feedback.</p></div><h2>Feedback</h2><p>If an interaction is difficult to use with assistive technology or on a particular device, contact <a href="mailto:tyeaawill@gmail.com">tyeaawill@gmail.com</a> with the page and device details.</p>`)}
  function cookies(){staticPage('Cookies & local storage',`<div class="prose-hero"><span class="eyebrow">Cookies</span><h2>Small pieces of storage help mindRID remember the session.</h2><p>mindRID may use browser storage for session state, navigation continuity, preferences and essential application behaviour.</p></div><h2>Control</h2><p>Browser settings can clear or restrict local storage and cookies. Some product functions may stop working if essential storage is blocked.</p>`)}
  function openAuth(mode){authMode=mode;modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');if(mode==='reset'){modal.innerHTML=`<div class="modal-card"><div class="modal-title"><div><div class="hint">mindRID</div><h2>Choose a new password</h2></div><button class="btn ghost" data-action="close">Close</button></div><form id="resetPasswordForm"><div class="field"><label>New password</label><input id="newPassword" type="password" minlength="6" autocomplete="new-password" required></div><div class="field"><label>Confirm new password</label><input id="confirmPassword" type="password" minlength="6" autocomplete="new-password" required></div><div id="resetMsg" class="status-line" aria-live="polite"></div><button class="btn auth-submit">Update password</button></form></div>`;return}if(mode==='forgot'){modal.innerHTML=`<div class="modal-card"><div class="modal-title"><div><div class="hint">mindRID</div><h2>Recover your account</h2></div><button class="btn ghost" data-action="close">Close</button></div><p class="hint">Enter your account email and we’ll send you a secure password-reset link.</p><form id="forgotPasswordForm"><div class="field"><label>Email</label><input id="recoveryEmail" type="email" autocomplete="email" required></div><div id="recoveryMsg" class="status-line" aria-live="polite"></div><button class="btn auth-submit">Send reset link</button></form><p class="auth-switch"><button class="action prominent-action" data-action="switch-signin">Back to sign in</button></p></div>`;return}modal.innerHTML=`<div class="modal-card"><div class="modal-title"><div><div class="hint">mindRID</div><h2>${mode==='signup'?'Create an account':'Welcome back'}</h2></div><button class="btn ghost" data-action="close">Close</button></div><form id="authForm"><div class="field"><label>Email</label><input id="email" type="email" autocomplete="email" required></div><div class="field"><label>Password</label><input id="password" type="password" minlength="6" autocomplete="current-password" required></div>${mode==='signup'?`<div class="field"><label>Username</label><input id="username" maxlength="30" required></div><div class="field"><label>Country (optional)</label><input id="signupCountry" maxlength="80"></div><div class="field"><label>City / area (optional)</label><input id="signupCity" maxlength="100"></div><div class="field"><label>Private identification</label><input id="identification" maxlength="500" required><div class="hint">Stored separately from your public profile. It is not shown with anonymous Whispers.</div></div><label class="check"><input id="identityAgree" type="checkbox" required> I understand that this identification is private account information.</label>`:''}<div id="authMsg" class="status-line" aria-live="polite"></div><button class="btn auth-submit">${mode==='signup'?'Create account':'Sign in'}</button></form><p class="auth-switch">${mode==='signup'?`Already registered? <button class="action prominent-action" data-action="switch-signin">Sign in</button>`:`<button class="action prominent-action" data-action="forgot-password">Forgot password?</button><br><span>Need an account?</span> <button class="action prominent-action" data-action="switch-signup">Create an account</button>`}</p></div>`}
  async function completeMfaIfRequired(){const factors=await client.auth.mfa.listFactors();if(factors.error)throw factors.error;const factor=(factors.data?.totp||[]).find(x=>x.status==='verified');if(!factor)return;const aal=await client.auth.mfa.getAuthenticatorAssuranceLevel();if(aal.error)throw aal.error;if(aal.data?.currentLevel==='aal2')return;const ch=await client.auth.mfa.challenge({factorId:factor.id});if(ch.error)throw ch.error;const code=prompt('Two-factor authentication is enabled. Enter your six-digit authenticator code:');if(!code)throw new Error('Two-factor authentication is required to sign in.');const v=await client.auth.mfa.verify({factorId:factor.id,challengeId:ch.data.id,code:code.trim()});if(v.error)throw v.error}
