  async function updateRecoveredPassword(){const a=document.getElementById('newPassword')?.value||'',b=document.getElementById('confirmPassword')?.value||'',msg=document.getElementById('resetMsg');if(a.length<6)throw new Error('Password must be at least 6 characters.');if(a!==b)throw new Error('Passwords do not match.');const r=await client.auth.updateUser({password:a});if(r.error)throw r.error;msg.textContent='Your password has been updated.';toast('Password updated.');recoveryPending=false;setTimeout(()=>{closeModal();window.history.replaceState(null,'',location.pathname);location.hash='#home'},700)}
  async function submitAuth(e){e.preventDefault();const form=e.target,btn=form.querySelector('.auth-submit'),msg=document.getElementById('authMsg');setBusy(btn, true, authMode==='signup'?'Creating account…':'Signing in…');msg.textContent=authMode==='signup'?'Creating your account…':'Signing you in…';try{if(!client)throw new Error('Supabase is still loading.');const email=document.getElementById('email').value.trim();const password=document.getElementById('password').value;if(authMode==='signup'){const rawUsername=document.getElementById('username').value.trim();const username=rawUsername.toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,30);if(username.length<3)throw new Error('Username must contain at least 3 letters, numbers or underscores.');const identification=document.getElementById('identification').value.trim();const signupCountry=document.getElementById('signupCountry')?.value.trim()||'';const signupCity=document.getElementById('signupCity')?.value.trim()||'';const r=await client.auth.signUp({email,password,options:{data:{username,display_name:username}}});if(r.error)throw r.error;if(!r.data.user)throw new Error('Account creation did not complete.');if(r.data.session){const pr=await client.from('profiles').upsert({id:r.data.user.id,username,display_name:username,location_country:signupCountry,location_city:signupCity});if(pr.error)throw pr.error;const ir=await client.from('private_identity').upsert({user_id:r.data.user.id,identification,updated_at:new Date().toISOString()});if(ir.error)throw ir.error;msg.textContent='Account created. You are ready to explore mindRID.';toast('Account created.');setTimeout(closeModal,700)}else{sessionStorage.setItem('mindrid_pending_identity',identification);msg.textContent='Account created, but Supabase email confirmation is still enabled. Turn off “Confirm email” in Supabase Auth settings to use the launch flow.';toast('Account created. One setup change is still required.','error')}}else{const r=await client.auth.signInWithPassword({email,password});if(r.error)throw r.error;await completeMfaIfRequired();await ensureProfile();await savePendingIdentity();msg.textContent='Signed in.';toast('Signed in.');setTimeout(closeModal,500)}}catch(e){msg.textContent=e.message||'Something went wrong.';toast(e.message||'Something went wrong.','error')}finally{setBusy(btn,false)}}
  function closeModal(){modal.classList.add('hidden');modal.setAttribute('aria-hidden','true');modal.innerHTML=''}
  async function save(el){if(!user){openAuth('signup');return}const root=activeComposerRoot();const text=root?.querySelector('#whisperText')?.value.trim()||'';const input=root?.querySelector('#whisperMedia');if(!text){toast('Write a reflection before attaching media.');return}const identity=root?.querySelector('#identity')?.value||'anonymous';const visibility=root?.querySelector('#visibility')?.value||'private';await runAction(el,'Posting…','Whisper shared.',async()=>{const recipients=await resolveRecipients();const media=await prepareFiles(input,'whisper');const w=await createWhisper(text,identity,visibility,recipients,media);const tags=collectTags();if(tags.length){try{await saveTags(w.id,tags)}catch(e){toast('Whisper shared. Some context tags could not be saved.','error')}}const vibe=tags.find(t=>t.tag_type==='vibe')?.tag_value||inferVibe(text);if(vibe&&user){currentProfile={...(currentProfile||{}),last_whisper_vibe:vibe};applyProfileTheme();client.from('profiles').update({last_whisper_vibe:vibe}).eq('id',user.id).then(()=>{}).catch(()=>{})}feedCache={};closeModal();location.hash=`#whisper/${encodeURIComponent(w.id)}`;return w})}
  function editMediaListHTML(media){if(!media?.length)return '<div class="empty">No media attached.</div>';return `<div class="edit-media-list">${media.map(m=>`<div class="edit-media-item" id="edit-media-${esc(m.id)}"><div class="edit-media-preview">${mediaPreview([m])}</div><div class="edit-media-meta"><strong>${esc(m.file_name||'Attachment')}</strong><span>${esc(m.mime_type||'Media')}</span></div><button type="button" class="btn danger" data-action="delete-edit-media" data-media-id="${esc(m.id)}">Delete media</button></div>`).join('')}</div>`}
  function editWhisper(id){getWhisper(id).then(async w=>{if(!w||w.author_id!==user?.id){toast('You can only edit your own Whisper.','error');return}const media=await listMedia('whisper',id).catch(()=>[]);modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');modal.innerHTML=`<div class="modal-card"><div class="modal-title"><h2>Edit reflection</h2><button class="btn ghost" data-action="close">Close</button></div><form id="editWhisperForm"><textarea id="editBody" maxlength="10000">${esc(w.body)}</textarea><div class="field"><label>Current media</label><div id="editExistingMedia">${editMediaListHTML(media)}</div></div>${attachmentPicker('edit')}<div class="field"><label>Identity</label><select id="editIdentity" class="select"><option value="anonymous" ${w.identity_mode==='anonymous'?'selected':''}>Anonymous</option><option value="real" ${w.identity_mode==='real'?'selected':''}>Me</option></select></div><div class="field"><label>Visibility</label><select id="editVisibility" class="select"><option value="public" ${w.visibility==='public'?'selected':''}>Public</option><option value="selected" ${w.visibility==='selected'?'selected':''}>People I choose</option><option value="private" ${w.visibility==='private'?'selected':''}>Private</option></select></div><div id="editRecipientBox" class="recipient-box ${w.visibility==='selected'?'':'hidden'}"><label>Recipients</label><input id="editRecipientNames" placeholder="Usernames, separated by commas"><div class="hint">Selected people will be able to see this reflection.</div></div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close">Cancel</button><button class="btn">Save changes</button></div></form></div>`;bindMediaPicker('edit');if(w.visibility==='selected'){const rr=await client.from('whisper_recipients').select('recipient_id').eq('whisper_id',id);if(!rr.error&&rr.data?.length){const ids=rr.data.map(x=>x.recipient_id);const pr=await client.from('profiles').select('username').in('id',ids);if(!pr.error)document.getElementById('editRecipientNames').value=(pr.data||[]).map(x=>x.username).join(', ')}}document.getElementById('editVisibility').addEventListener('change',()=>document.getElementById('editRecipientBox')?.classList.toggle('hidden',document.getElementById('editVisibility').value!=='selected'))})}
  async function submitEdit(e){e.preventDefault();const btn=e.target.querySelector('.btn:not(.ghost)');await runAction(btn,'Saving…','Reflection updated.',async()=>{const w=await getWhisper(currentWhisper?.id||decodeURIComponent((location.hash.match(/^#whisper\/(.+)$/)||[])[1]||''));if(!w)throw new Error('Whisper unavailable.');const newBody=document.getElementById('editBody').value.trim();const input=document.getElementById('editMedia');if(!newBody&&(input?.files?.length||0)===0&&!(await listMedia('whisper',w.id)).length)throw new Error('Write something or keep media attached.');const media=await prepareFiles(input,'edit');const visibility=document.getElementById('editVisibility').value;let recipients=[];if(visibility==='selected'){const names=(document.getElementById('editRecipientNames')?.value||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);if(!names.length)throw new Error('Choose at least one recipient for a selected Whisper.');const r=await client.from('profiles').select('id,username').in('username',names);if(r.error)throw r.error;const found=r.data||[];const missing=names.filter(n=>!found.some(x=>x.username===n));if(missing.length)throw new Error(`Could not find: ${missing.join(', ')}`);recipients=found.map(x=>x.id)}await updateWhisper(w.id,newBody,document.getElementById('editIdentity').value,visibility,recipients,media);closeModal();await openWhisper(w.id)})}
