    modal.innerHTML=`<div class="mobile-composer-card"><div class="mobile-composer-head"><strong>Create reflection</strong><button class="btn ghost" data-action="close">Cancel</button></div>${composer()}<div class="mobile-composer-footer"><button class="btn" data-action="save">Whisper</button></div></div>`;
