  function bindComposer(root=activeComposerRoot()){const ta=root?.querySelector('#whisperText'),ms=root?.querySelector('#whisperMentionSuggestions');if(ta&&ms){let mt;ta.addEventListener('input',()=>{clearTimeout(mt);const m=ta.value.match(/(?:^|\s)@([a-zA-Z0-9_]*)$/);if(!m||m[1].length<1){ms.innerHTML='';return}mt=setTimeout(async()=>{try{const rows=await searchNetworkProfiles(m[1]);ms.innerHTML=rows.map(p=>profileSuggestionHTML(p,'mention')).join('')}catch{ms.innerHTML=''}},120)});}const vis=root?.querySelector('#visibility');vis?.addEventListener('change',()=>root?.querySelector('#recipientBox')?.classList.toggle('hidden',vis.value!=='selected'));const recipientInput=root?.querySelector('#recipientNames'),recipientList=root?.querySelector('#recipientSuggestions');if(recipientInput&&recipientList){let rt;recipientInput.addEventListener('input',()=>{clearTimeout(rt);const q=recipientInput.value.split(',').pop().trim().replace(/^@/,'');if(q.length<2){recipientList.innerHTML='';return}rt=setTimeout(async()=>{try{const rows=await searchProfiles(q);recipientList.innerHTML=rows.slice(0,8).map(p=>`<button type="button" class="suggestion" data-action="recipient-suggestion" data-user="${esc(p.username)}"><span class="avatar small">${esc((p.display_name||p.username||'P')[0].toUpperCase())}</span><span><strong>${esc(p.display_name||p.username)}</strong><small>@${esc(p.username)}</small></span></button>`).join('')||'<div class="suggestion">No matching people.</div>'}catch{recipientList.innerHTML=''}},180)})}const loc=root?.querySelector('#tagLocation'),locBox=root?.querySelector('#locationSuggestions');if(loc&&locBox){let lt;loc.addEventListener('input',()=>{clearTimeout(lt);const q=loc.value.trim();if(q.length<3){locBox.innerHTML='';return}lt=setTimeout(async()=>{try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&q=${encodeURIComponent(q)}`);if(!r.ok)throw new Error('Place search unavailable');const rows=await r.json();locBox.innerHTML=rows.map(x=>`<button type="button" class="suggestion" data-action="select-location" data-place="${esc(x.display_name)}">${esc(x.display_name)}</button>`).join('');if(!rows.length)locBox.innerHTML='<div class="suggestion">No matching places. You can keep your own wording.</div>'}catch{locBox.innerHTML=''}} ,500)})}for(const key of ['Feeling','Idea','Vibe']){const sel=root?.querySelector('#tag'+key),custom=root?.querySelector('#tag'+key+'Custom');sel?.addEventListener('change',()=>{custom?.classList.toggle('hidden',sel.value!=='__custom');if(sel.value==='__custom')custom?.focus()})}bindMediaPicker('whisper',root)}
